/* Clean MONA CSS rebuild for nhtq: browser-extension styles excluded; original html/body semantics preserved. */
.mona-clone-root.mona-nhtq{--mona-rem:10px;width:100%;max-width:none;margin:0;padding:0;position:relative;overflow-x:clip;font-family:'NeueMontreal',system-ui,-apple-system,'Segoe UI',sans-serif;}
.mona-clone-root.mona-nhtq :where(.mona-html, .mona-html *){all:revert;box-sizing:border-box;}
.mona-clone-root.mona-nhtq .mona-html,.mona-clone-root.mona-nhtq .mona-body{display:block;width:100%;max-width:none;min-width:0;margin:0;padding:0;position:relative;}
@media (max-width:1580px){.mona-clone-root.mona-nhtq{--mona-rem:8px;}}
@media (max-width:1200px){.mona-clone-root.mona-nhtq{--mona-rem:10px;}}
@media (min-width:2000px){.mona-clone-root.mona-nhtq{--mona-rem:12.8px;}}
@media (min-width:2500px){.mona-clone-root.mona-nhtq{--mona-rem:16px;}}

/* source: inline */
.mona-clone-root.mona-nhtq img.wp-smiley, .mona-clone-root.mona-nhtq img.emoji{
	display: inline !important;
	border: none !important;
	box-shadow: none !important;
	height: 1em !important;
	width: 1em !important;
	margin: 0 0.07em !important;
	vertical-align: -0.1em !important;
	background: none !important;
	padding: 0 !important;
}
